window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-06-17"]={"date":"2026-06-17","dateKR":"2026년 6월 17일","dateEN":"17 June 2026","total":101,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. Top News","eTitle":"Section 1. Top News","items":[{"code":"TOP-1","title":"걸프·호르무즈·홍해 해상보안 업데이트","src":"Hellenic Shipping News","date":"2026-06","kSum":"걸프 지역·호르무즈 해협·홍해의 해상보안 상황을 종합한 업데이트가 발표됐다. 위협수준·안전항로·권고사항이 갱신되며 선사들이 항로 결정에 활용하고 있다.","eSum":"A maritime security update covered the Gulf region, Strait of Hormuz and Red Sea, refreshing threat levels, safe-routing advice and recommendations that operators are using for routing decisions.","kImp":"해상보안 업데이트를 정기 반영해 항로·보고체계를 최신 상태로 유지해야 한다.","eImp":"Regularly incorporate security updates to keep routing and reporting current.","url":"https://www.hellenicshippingnews.com/maritime-security-update-gulf-region-strait-of-hormuz-and-red-sea-2/"},{"code":"TOP-2","title":"호르무즈 해협 \"첫 36시간\" — 탱커 피격·걸프 통항 중단","src":"gCaptain","date":"2026-06","kSum":"호르무즈 해협이 사실상 전장으로 변하며 다수의 탱커가 피격되고 주요 선사들이 걸프 통항을 중단했다. 이란은 6월 11일 해협을 모든 선박에 대해 폐쇄한다고 선언했고, 통항은 일평균 약 138척에서 3~6척 수준으로 급감했다.","eSum":"The Strait of Hormuz became a war zone in the first 36 hours with tankers hit and shipping giants halting Gulf transits. Iran declared the strait closed to all vessels on 11 June; daily transits collapsed from a historical average near 138 to just 3-6.","kImp":"걸프 의존 항로의 BCP·대체 항로(희망봉 등) 시나리오를 즉시 점검해야 한다.","eImp":"Review BCP and alternative-routing scenarios for Gulf-dependent trades immediately.","url":"https://gcaptain.com/the-first-36-hours-strait-of-hormuz-becomes-a-war-zone-tankers-hit-shipping-giants-halt-gulf-transits"},{"code":"TOP-3","title":"24시간 내 두 번째 선박 피격 — 美·이란 호르무즈 긴장","src":"TradeWinds","date":"2026-06","kSum":"미·이란 간 호르무즈 줄다리기 속에서 24시간 만에 두 번째 상선이 피격됐다. 미 해군은 4월 이후 아라비아해·오만만에서 9척에 미사일을 발사했으며, 이란은 자국 봉쇄를 강제하려 하고 있다.","eSum":"A second merchant ship was hit within 24 hours amid the US-Iran tug-of-war in the Strait of Hormuz. The US Navy has fired on nine vessels in the Arabian Sea and Gulf of Oman since April as Iran tries to enforce its blockade.","kImp":"단기간 반복 피격은 전쟁위험요율 추가 인상과 선원 승선 거부로 이어질 수 있다.","eImp":"Repeated strikes risk further war-risk rate hikes and crew refusal to sail.","url":"https://www.tradewindsnews.com/tankers/second-ship-hit-in-24-hours-amid-us-iran-tug-of-war-in-the-strait-of-hormuz/2-1-2003679"},{"code":"TOP-4","title":"호르무즈 위험 감수 항행 — 남부 오만 영해 경유 통항","src":"The Maritime Executive","date":"2026-06","kSum":"일부 선박은 오만 영해를 통한 남측 항로로 호르무즈를 위험을 감수하며 통항하고 있다. 위협수준은 6월 7일 CRITICAL에서 SEVERE로 하향됐으나 통항량은 역대 평균을 크게 밑돈다.","eSum":"Some vessels are braving the dangers of the Strait of Hormuz via the southern route through Omani waters. The threat level was reduced from CRITICAL to SEVERE on 7 June, though traffic remains far below historical norms.","kImp":"오만 영해 경유 항로의 사전 통보·호송·감시 체계를 점검해야 한다.","eImp":"Verify advance-notification, convoy and monitoring arrangements for the Omani-waters route.","url":"https://maritime-executive.com/article/braving-the-dangers-in-the-strait-of-hormuz"},{"code":"TOP-5","type":"news","title":"호르무즈 탱커 피격, 美 '비밀 작전' 새 의혹 제기","src":"gCaptain","date":"2026-06-16","kSum":"호르무즈 해협 탱커 피격을 두고 미국의 '비밀 작전(secret mission)'에 대한 새로운 의혹이 제기됐다. 미·이란 긴장 속 민간 상선 안전을 둘러싼 책임 공방이 이어지고 있다.","eSum":"The latest tanker attack has raised new questions about a US 'secret mission' in the Strait of Hormuz, fuelling a dispute over responsibility for commercial-ship safety amid US-Iran tension.","kImp":"사건 책임 불확실성이 전쟁위험 보험·항로 판단의 변수로 작용한다.","eImp":"Uncertainty over responsibility complicates war-risk insurance and routing decisions.","url":"https://gcaptain.com/tanker-attack-raises-new-questions-about-u-s-secret-mission-in-hormuz/"},{"code":"TOP-6","type":"news","title":"호르무즈 통항 급감…美, 신규 제재 탱커 나포","src":"Seatrade Maritime","date":"2026-06-16","kSum":"호르무즈 해협 통항량이 급감한 가운데 미국이 신규 제재 대상 탱커를 나포했다. 그림자 선단 단속과 봉쇄가 동시에 진행되며 통항 위축이 심화되고 있다.","eSum":"Hormuz transits have dried up as the US intercepted a newly sanctioned tanker, with shadow-fleet enforcement and the blockade together deepening the collapse in traffic.","kImp":"제재·봉쇄 병행으로 합법 선박의 통항 예측가능성이 더 낮아진다.","eImp":"Combined sanctions and blockade further reduce predictability for legitimate transits.","url":"https://www.seatrade-maritime.com/security/hormuz-transits-dry-up-us-intercepts-newly-sanctioned-tanker"},{"code":"TOP-7","type":"news","title":"제재 대상 탱커, 호르무즈서 U턴","src":"Seatrade Maritime","date":"2026-06-16","kSum":"제재 대상 탱커가 호르무즈 해협 진입 직전 항로를 되돌리는 U턴을 했다. 단속·피격 위험 고조로 선박들이 진입을 회피하고 있다.","eSum":"A sanctioned tanker pulled a U-turn at the Strait of Hormuz, as heightened enforcement and attack risk push vessels to avoid entry.","kImp":"고위험 진입 회피가 늘며 걸프 물류·운임 변동성이 커진다.","eImp":"More avoidance of high-risk entry increases Gulf logistics and freight volatility.","url":"https://www.seatrade-maritime.com/security/sanctioned-tanker-pulls-strait-of-hormuz-u-turn"},{"code":"TOP-8","type":"news","title":"유조선들, AIS 끄고 호르무즈로 걸프산 원유 밀반출","src":"gCaptain","date":"2026-06-16","kSum":"일부 유조선이 AIS(선박자동식별장치)를 끈 채 '다크(dark)' 운항으로 호르무즈를 통해 걸프산 원유를 더 실어 나르고 있다. 단속·위험 회피와 물량 확보가 맞물린 결과다.","eSum":"Oil tankers are going dark — switching off AIS — to sneak more Gulf barrels through Hormuz, balancing enforcement/attack avoidance against the pull of cargo volumes.","kImp":"다크 운항 증가는 충돌·식별 위험과 보험·컴플라이언스 리스크를 키운다.","eImp":"More dark operation raises collision/identification risk and insurance/compliance exposure.","url":"https://gcaptain.com/oil-tankers-go-dark-to-sneak-more-gulf-barrels-through-hormuz/"},{"code":"TOP-9","type":"news","title":"탱커 2척, 호르무즈 해협 빠져나가","src":"MarineLink","date":"2026-06-16","kSum":"탱커 2척이 호르무즈 해협을 빠져나간 것으로 확인됐다. 극소수 선박만이 위험을 감수하며 통항을 이어가는 상황을 보여준다.","eSum":"Two tankers exited the Strait of Hormuz, illustrating that only a handful of vessels are still braving the passage.","kImp":"통항 선박 급감은 유가·운임·공급망에 지속적 압력을 가한다.","eImp":"Sharply reduced transits keep pressure on oil prices, freight and supply chains.","url":"https://www.marinelink.com/news/two-tankers-exit-strait-hormuz-538998"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. Accidents (해상 사고)","eTitle":"Section 2. Accidents","items":[{"code":"ACC-1","title":"미시시피강 충돌·기름유출 — 美 비상대응","src":"Riviera Maritime Media","date":"2026-06","kSum":"미국 연안에서 선박 충돌에 따른 기름유출과 바지선 화재가 발생해 USCG 주도의 비상대응이 전개됐다. 방제선·오일펜스 전개로 확산을 차단했다.","eSum":"A US emergency response was mounted for a vessel collision, oil spill cleanup and barge fire, with the Coast Guard coordinating containment and skimming operations.","kCause":"조류·교행 상황에서의 조선(操船) 판단 및 통항 분리 미준수 가능성(조사 진행 중).","eCause":"Possible shiphandling/COLREG separation issues in current-affected crossing traffic (under investigation).","kLes":"내수면 교행구간 BRM·VTS 교신 강화, SOPEP 즉시 가동 체계 점검(MARPOL Annex I).","eLes":"Strengthen BRM/VTS communication in inland crossing zones; verify immediate SOPEP activation (MARPOL Annex I).","url":"https://www.rivieramm.com/news-content-hub/us-emergency-response-vessel-collision-oil-spill-cleanup-88287"},{"code":"ACC-2","title":"탱커 2척 화재 — 전원 구조·자체 소화 대응","src":"Seatrade Maritime","date":"2026-06","kSum":"충돌·화재가 발생한 탱커 2척에서 선원 전원이 구조되거나 소화 작업에 투입됐다. 인명 피해 없이 초기 대응이 이뤄졌다.","eSum":"On the two blazing tankers, all crew were either rescued or involved in firefighting, with initial response managed without loss of life.","kCause":"충돌에 따른 화물·연료 누출 점화(조사 진행 중).","eCause":"Ignition of leaked cargo/fuel following collision (under investigation).","kLes":"비상소집·퇴선훈련 숙달과 구명설비(LSA) 즉시 가용성 확보가 생존의 관건.","eLes":"Drilled muster/abandon-ship and immediate LSA availability are decisive for survival.","url":"https://www.seatrade-maritime.com/accidents/blaze-on-two-tankers-all-crew-rescued-or-involved-in-firefighting"},{"code":"ACC-3","title":"좌초 페리에서 승객 구조 — 선체 경사","src":"SAFETY4SEA","date":"2026-06","kSum":"좌초로 선체가 기운 페리에서 승객들이 구조됐다. 천수·항로 이탈이 좌초로 이어진 것으로 추정된다.","eSum":"Passengers were rescued off a listing ferry after a grounding incident, with shallow water/off-track navigation suspected as the cause.","kCause":"수심 확인·항로 유지 미흡 및 항해계획 검증 부족 가능성.","eCause":"Possible inadequate depth checking, track-keeping and passage-plan verification.","kLes":"여객선 비상소집·구명벌 운용 절차 숙달 및 항해계획(Passage Plan) 검증 강화(SOLAS Ch.V).","eLes":"Drill passenger muster/liferaft procedures and strengthen passage-plan checks (SOLAS Ch.V).","url":"https://safety4sea.com/passengers-rescued-off-listing-ferry-after-grounding-incident/"},{"code":"ACC-4","title":"홍콩 선적 탱커, 오만 외해서 피격·손상","src":"The Maritime Executive","date":"2026-06","kSum":"홍콩 선적 탱커가 오만 연안 약 6해리 해상에서 출항 중 발사체에 피격됐다. 좌현 선수가 맞아 밸러스트 탱크 손상과 화물 누출이 발생했다.","eSum":"A Hong Kong-flagged tanker was struck by a projectile about six nautical miles off Oman while outbound. The impact hit the port bow, damaging a ballast tank and causing a cargo leak.","kCause":"지역 무력충돌에 따른 의도적 공격(군사적 요인).","eCause":"Deliberate attack arising from the regional armed conflict (military factor).","kLes":"전쟁위험구역 진입 전 BMP·하드닝 조치, 손상통제(Damage Control) 대비 강화(ISPS).","eLes":"Apply BMP/hardening before entering war-risk areas and reinforce damage-control readiness (ISPS).","url":"https://maritime-executive.com/article/hong-kong-flagged-tanker-hit-and-damaged-in-strait-of-hormuz"},{"code":"ACC-5","title":"이란, 호르무즈서 탱커에 사격·컨테이너선 피격","src":"Seatrade Maritime","date":"2026-06","kSum":"이란이 호르무즈 해협에서 탱커에 사격을 가했고 컨테이너선도 피격됐다. 민간 상선에 대한 직접 공격이 반복되고 있다.","eSum":"A tanker was fired on by Iran in the Strait of Hormuz and a container ship was struck, with direct attacks on commercial shipping recurring.","kCause":"봉쇄 강제를 위한 의도적 공격.","eCause":"Deliberate attacks to enforce a blockade.","kLes":"선종 무관 전 선대에 전쟁위험구역 회피·보고체계(UKMTO 등) 적용 필요.","eLes":"Apply war-risk avoidance and reporting (e.g. UKMTO) fleet-wide regardless of ship type.","url":"https://www.seatrade-maritime.com/security/tanker-fired-on-by-iran-in-strait-of-hormuz"},{"code":"ACC-6","title":"탱커 Settebello 피격 — 인도·IMO 규탄","src":"Seatrade Maritime","date":"2026-06","kSum":"Palau 선적 탱커 Settebello의 기관실이 6월 10일 피격돼 인도 선원 3명이 실종됐고, 인도 정부와 IMO가 공격을 규탄했다. 미군 작전 과정에서 발생한 것으로 보도됐다.","eSum":"The engine room of the Palau-flagged tanker Settebello was struck on 10 June leaving three Indian seafarers missing; India and the IMO condemned the attack, reportedly linked to US operations.","kCause":"지역 무력충돌 중 선박 오인·표적 공격 가능성(조사·논란 진행 중).","eCause":"Possible misidentification/targeting during the armed conflict (disputed, under investigation).","kLes":"선원 안전을 최우선으로 고위험 해역 항행 자제·전쟁위험 보고체계 준수(MLC 선원보호).","eLes":"Prioritise crew safety, avoid high-risk transits and follow war-risk reporting (MLC crew protection).","url":"https://www.seatrade-maritime.com/security/india-and-the-imo-condemn-attack-on-tanker-settebello"}]},{"code":"PSC","type":"news","kTitle":"Section 3. PSC (Port State Control)","eTitle":"Section 3. PSC (Port State Control)","items":[{"code":"PSC-1","title":"DNV: 2026년 1분기 PSC 억류 리뷰 — 전년比 증가","src":"Hellenic Shipping News","date":"2026-Q1","kSum":"DNV 선대의 2026년 1분기 억류는 64건으로 2025년 동기 52건 대비 늘었고, 약 84%가 Paris·Tokyo MoU에서 발생했다. 1~3월 Paris·Tokyo·USCG 합산 억류는 601건이었다.","eSum":"DNV recorded 64 detentions in Q1 2026, up from 52 a year earlier, with about 84% in the Paris and Tokyo MoUs. A total of 601 detentions were logged across Paris MoU, Tokyo MoU and USCG in Q1.","kImp":"ISM·정비·소방 결함이 억류를 주도 — 출항 전 자체점검 항목을 강화해야 한다.","eImp":"ISM, maintenance and fire-safety deficiencies drive detentions; strengthen pre-departure self-checks.","url":"https://www.hellenicshippingnews.com/dnv-port-state-control-q1-2026-detention-review-and-other-updates/"},{"code":"PSC-2","title":"DNV: 억류가 ISM 이행·소방 결함 노출","src":"SAFETY4SEA","date":"2026","kSum":"DNV는 2026년 1분기 억류가 ISM 이행 미흡과 소방 안전 결함을 드러냈다고 분석했다. 가장 빈번한 지적은 '15150-ISM'과 '15109-선박·설비 정비'였다.","eSum":"DNV analysis shows detentions reveal shortcomings in ISM implementation and fire safety, with the most cited deficiencies being '15150 – ISM' and '15109 – maintenance of ship and equipment'.","kImp":"ISM·정비 결함 코드에 집중한 출항 전 자체점검 체크리스트 강화가 필요하다.","eImp":"Strengthen pre-departure self-checks focused on ISM and maintenance deficiency codes.","url":"https://safety4sea.com/dnv-detentions-show-shortcomings-in-ism-implementation-fire-safety/"},{"code":"PSC-3","title":"USCG: \"모든 선박을 점검할 수는 없다\" — 위험기반 선별 강화","src":"gCaptain","date":"2026","kSum":"USCG는 한정된 인력으로 모든 선박을 점검할 수 없다며 위험기반 선별을 강화하고 있다고 밝혔다. 고위험 프로파일 선박에 점검이 집중된다.","eSum":"The US Coast Guard said it cannot inspect all vessels and is intensifying risk-based targeting, concentrating inspections on higher-risk-profile ships.","kImp":"결함 이력·억류 기록 관리로 고위험 프로파일 분류를 피하는 것이 중요하다.","eImp":"Managing deficiency and detention history is key to avoiding a high-risk classification.","url":"https://gcaptain.com/coast-guard-on-port-state-control-we-cant-inspect-all-of-them/"},{"code":"PSC-4","title":"AMSA: 외국적선 PSC 핵심 점검 분야 발표","src":"SAFETY4SEA","date":"2026","kSum":"AMSA는 외국적선 대상 최소 2,400건의 PSC 점검을 강화된 위험 프로파일링 알고리즘으로 수행하겠다고 밝혔다. 선상 정비 미흡이 호주 억류의 주요 원인으로 지속 지목됐다.","eSum":"AMSA will conduct a minimum of 2,400 PSC inspections on foreign-flagged vessels using an enhanced risk-profiling algorithm. Shipboard maintenance remains a leading cause of detention in Australia.","kImp":"호주 입항선은 정비기록·PMS 증빙을 사전 점검해 억류 위험을 낮춰야 한다.","eImp":"Vessels calling Australia should pre-verify maintenance records/PMS evidence to cut detention risk.","url":"https://safety4sea.com/amsa-key-psc-focus-areas-for-foreign-flagged-vessels/"},{"code":"PSC-5","type":"news","title":"PSC, 신규 캠페인·제한에 대비하라","src":"Hellenic Shipping News","date":"2026-06","kSum":"Paris·Tokyo MoU가 9월 1일~11월 30일 화물 고박(cargo securing)에 관한 합동 집중점검캠페인(CIC)을 준비 중이다. 선사들은 신규 캠페인과 입항 제한에 대비해 관련 절차·기록을 사전 점검해야 한다.","eSum":"The Paris and Tokyo MoUs are preparing a joint Concentrated Inspection Campaign (CIC) on cargo securing for 1 Sept-30 Nov; operators should prepare for new campaigns and restrictions by pre-checking related procedures and records.","kImp":"고박 CIC 대비 화물 고박 매뉴얼·점검표·증빙을 사전 정비해야 한다.","eImp":"Prepare cargo-securing manuals, checklists and evidence ahead of the securing CIC.","url":"https://www.hellenicshippingnews.com/port-state-control-be-prepared-for-new-campaigns-and-restrictions/"},{"code":"PSC-6","type":"news","title":"항만국통제 — 2분기(Q2) 억류 요약","src":"Hellenic Shipping News","date":"2026-06","kSum":"2026년 2분기 PSC 억류 요약이 발표됐다. ISM 이행·정비·소방 관련 결함이 지속적으로 억류를 주도하고 있어 출항 전 자체점검 강화가 요구된다.","eSum":"A summary of Q2 2026 PSC detentions was published, with ISM-implementation, maintenance and fire-safety deficiencies continuing to drive detentions, underscoring the need for stronger pre-departure self-checks.","kImp":"분기별 억류 패턴을 SMS 시정조치·내부심사에 반영해야 한다.","eImp":"Feed quarterly detention patterns into SMS corrective action and internal audits.","url":"https://www.hellenicshippingnews.com/port-state-control-a-summary-of-q2-detentions-2/"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. PCTC / Car Carrier","eTitle":"Section 4. PCTC / Car Carrier","items":[{"code":"PCTC-1","title":"현대글로비스(Hyundai Glovis), 세계 최대 자동차운반선 발주 추진","src":"Splash 247","date":"2026","kSum":"현대글로비스(Hyundai Glovis)가 세계 최대 규모의 자동차운반선 발주를 추진하고 있다. 장기용선 기반으로 선대를 대폭 확충해 완성차 수송 수요 증가에 대응한다.","eSum":"Hyundai Glovis is lining up orders for the world's largest car carriers, expanding its fleet via long-term charters to meet rising finished-vehicle transport demand.","kImp":"초대형 PCTC 발주 경쟁은 선복 공급 증가와 운임 변동성 확대로 이어진다.","eImp":"The race for mega-PCTC orders adds tonnage supply and freight volatility.","url":"https://splash247.com/hyundai-glovis-lines-up-orders-for-worlds-largest-car-carriers/"},{"code":"PCTC-2","title":"Seaspan, 현대글로비스(Hyundai Glovis) 향 최대급 자동차운반선 발주","src":"The Maritime Executive","date":"2026","kSum":"Seaspan이 현대글로비스(Hyundai Glovis) 장기용선용으로 시장 최대급 자동차운반선을 발주했다. 선주사·운영사 간 장기용선 구조로 초대형 PCTC 공급이 확대되고 있다.","eSum":"Seaspan ordered some of the largest car carriers entering the market for long-term charter to Hyundai Glovis, expanding mega-PCTC supply through owner-operator charter structures.","kImp":"장기용선 기반 대형 발주는 선복 공급 안정과 운임 변동성에 영향을 준다.","eImp":"Large charter-backed orders affect tonnage supply stability and freight volatility.","url":"https://maritime-executive.com/article/seaspan-orders-largest-car-carriers-entering-market-with-hyundai-glovis"},{"code":"PCTC-3","title":"HMM, Seaspan에 맞춰 현대글로비스 용선 대규모 자동차운반선 발주","src":"Splash 247","date":"2026","kSum":"HMM이 Seaspan에 이어 현대글로비스(Hyundai Glovis) 용선용 대규모 자동차운반선을 발주했다. 한국 화주·운영사 주도의 초대형 PCTC 확보 경쟁이 가열되고 있다.","eSum":"HMM matched Seaspan with a massive car carrier order for Hyundai Glovis charter, intensifying Korean-led competition to secure mega-PCTC capacity.","kImp":"화주 주도 대형 발주는 완성차 물류 공급망 재편을 가속한다.","eImp":"Shipper-led large orders accelerate restructuring of finished-vehicle logistics.","url":"https://splash247.com/hmm-matches-seaspan-in-massive-car-carriers-order-for-hyundai-glovis-charter/"},{"code":"PCTC-4","title":"UECC, 前 Höegh 자동차운반선 편입으로 선대 확장","src":"The Maritime Executive","date":"2026","kSum":"UECC가 Höegh Autoliners로부터 2006년 건조 'Höegh Chiba'를 인수해 'Auto Way'로 개명하고 장기용선으로 남북항로에 투입했다. 보유·용선 선대가 14척으로 늘었다.","eSum":"UECC acquired the 2006-built Höegh Chiba, renamed Auto Way, on long-term charter for North-South trade, lifting its fleet to 14 owned and chartered units.","kImp":"중고선 편입을 통한 단기 선복 확보가 신조 인도 공백을 메우고 있다.","eImp":"Second-hand additions bridge tonnage gaps ahead of newbuild deliveries.","url":"https://maritime-executive.com/corporate/uecc-renewed-fleet-expansion-with-addition-of-ex-hoegh-car-carrieri"},{"code":"PCTC-5","type":"news","title":"MacGregor, Höegh Aurora급 PCTC 4척 RoRo 장비 추가 수주 — 12척으로 확대","src":"Hellenic Shipping News","date":"2026-06","kSum":"MacGregor가 Höegh Autoliners의 Aurora급 PCTC 4척에 대한 종합 RoRo 장비 공급 계약을 추가 수주하며 Aurora급 신조 프로그램이 12척으로 확대됐다. 전 선박은 China Merchant Heavy Industries(Jiangsu)에서 건조돼 2026년 2분기~2027년 상반기 인도 예정이다.","eSum":"MacGregor won a further order to supply comprehensive RoRo equipment for four Aurora-class PCTCs for Höegh Autoliners, extending the Aurora-class program to twelve ships, all built by China Merchant Heavy Industries (Jiangsu) for delivery between Q2 2026 and H1 2027.","kImp":"Aurora급 확대는 대체연료 레디 대형 PCTC 공급 증가를 가속한다.","eImp":"The Aurora-class expansion accelerates supply of large, alt-fuel-ready PCTCs.","url":"https://www.hellenicshippingnews.com/macgregor-has-received-a-significant-order-to-supply-comprehensive-roro-equipment-to-hoegh-autoliners-four-pctc-vessels/"}]},{"code":"WW","type":"news","kTitle":"Section 5. Wallenius Wilhelmsen","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW-1","title":"Wallenius Wilhelmsen, 신조 4척 '역대 최대급'으로 상향","src":"Seatrade Maritime","date":"2026","kSum":"Wallenius Wilhelmsen이 신조 자동차운반선 4척을 역대 최대급으로 상향(upsize) 발주했다. Shaper class 시리즈의 대형화로 단위 수송효율을 높이려는 전략이다.","eSum":"Wallenius Wilhelmsen is upsizing four newbuild car carriers to the largest it has ever ordered, enlarging its Shaper-class series to boost per-unit transport efficiency.","kImp":"대형화는 규모의 경제를 키우나 항만 적합성·하역 인프라 검토가 필요하다.","eImp":"Upsizing improves scale economics but requires port-compatibility and handling review.","url":"https://www.seatrade-maritime.com/shipyards/wallenius-wilhelmsen-upsizing-four-newbuild-car-carriers-to-largest-ever"},{"code":"WW-2","title":"Wallenius Wilhelmsen, 메탄올 이중연료 PCTC 4척 옵션 행사","src":"Riviera Maritime Media","date":"2026","kSum":"Wallenius Wilhelmsen이 메탄올 이중연료 PCTC 4척에 대한 옵션을 행사했다. 탈탄소 대응을 위한 대체연료 선대 확충이 본격화되고 있다.","eSum":"Wallenius Wilhelmsen took options on four methanol dual-fuel PCTCs, accelerating expansion of its alternative-fuel fleet for decarbonisation.","kImp":"메탄올 이중연료 채택 확대는 연료 공급망·벙커링 인프라 확보 과제를 동반한다.","eImp":"Wider methanol dual-fuel adoption brings fuel-supply and bunkering-infrastructure challenges.","url":"https://www.rivieramm.com/news-content-hub/wallenius-wilhelmsen-takes-options-on-pctc-quartet-79822"},{"code":"WW-3","title":"Wallenius Wilhelmsen, 전 부문 개선된 강한 분기 실적","src":"Hellenic Shipping News","date":"2026","kSum":"Wallenius Wilhelmsen이 전 사업부문에서 개선된 강한 분기 실적을 발표했다. 해운 부문은 물량 증가와 항해효율 개선으로 EBITDA 4억7,700만 달러, 영업현금흐름 3억9,600만 달러를 기록했다.","eSum":"Wallenius Wilhelmsen delivered another strong quarter improving performance across all segments, with shipping posting USD 477m EBITDA and USD 396m operating cash flow on higher volumes and voyage efficiency.","kImp":"PCTC 시장 호황 지속으로 캐시플로우 기반의 신조 투자 여력이 유지된다.","eImp":"A buoyant PCTC market sustains cash-flow-backed newbuild investment capacity.","url":"https://www.hellenicshippingnews.com/wallenius-wilhelmsen-asa-wallenius-wilhelmsen-delivers-another-strong-quarter-improving-performance-across-all-segments/"},{"code":"WW-4","title":"Wallenius Wilhelmsen, Shaper class 추가 4척 발주","src":"gCaptain","date":"2026","kSum":"Wallenius Wilhelmsen이 Shaper class PCTC 4척을 추가 발주했다. 총 14척의 Shaper class(11,700 CEU 8척·9,300 CEU 6척)를 발주 잔량으로 보유하고 있다.","eSum":"Wallenius Wilhelmsen ordered four more Shaper-class PCTCs. It now has 14 Shaper-class vessels on order, comprising eight 11,700-CEU and six 9,300-CEU units.","kImp":"대규모 발주잔량은 2026~2027년 선대 갱신·수송능력 확대를 뒷받침한다.","eImp":"A large orderbook underpins fleet renewal and capacity growth through 2026-2027.","url":"https://gcaptain.com/wallenius-wilhelmsen-orders-four-more-shaper-class-pctcs/"},{"code":"WW-5","title":"Wallenius Wilhelmsen, 차세대 RoRo 발주 — 강한 수요","src":"The Maritime Executive","date":"2026","kSum":"Wallenius Wilhelmsen이 부문 수요 강세 속에 차세대 RoRo를 발주했다. 첫 4척은 2026년 하반기, 다음 4척은 2027년 5~11월 인도 예정이며 2026년 선복은 약 90% 확보됐다.","eSum":"Wallenius Wilhelmsen ordered next-gen RoRos as the sector sees strong demand. The first four deliver in H2 2026 and the next four between May and November 2027, with 2026 around 90% covered.","kImp":"높은 선복 커버리지는 운임 변동성에 대한 방어력을 제공한다.","eImp":"High coverage provides resilience against freight-rate volatility.","url":"https://maritime-executive.com/article/wallenius-wilhelmsen-orders-next-gen-roros-as-sector-sees-strong-demand"},{"code":"WW-6","title":"Wallenius Wilhelmsen, 4척 '역대 최대 PCTC'로 상향","src":"Marine Insight","date":"2026","kSum":"Wallenius Wilhelmsen이 4척을 역대 최대급 PCTC로 상향 건조하기로 했다. 단일 항차 수송량 극대화를 통한 단위 탄소집약도 개선이 목표다.","eSum":"Wallenius Wilhelmsen will upsize four vessels into the largest PCTCs it has ever built, targeting maximum per-voyage volumes and improved carbon intensity per unit.","kImp":"대형화·고효율화는 CII 등급 관리와 단위원가 절감에 기여한다.","eImp":"Upsizing and efficiency aid CII-rating management and unit-cost reduction.","url":"https://www.marineinsight.com/shipping-news/wallenius-wilhelmsen-to-upsize-4-vessels-into-the-largest-pctcs-ever-built/"},{"code":"WW-7","title":"Wallenius, 자동차운반선 옵션 상향·확정","src":"Seatrade Maritime","date":"2026","kSum":"Wallenius가 자동차운반선 옵션을 상향(upsize)하고 확정(firm)했다. 발주 옵션의 본계약 전환으로 중장기 선대 계획이 구체화되고 있다.","eSum":"Wallenius upsized and firmed car carrier options, converting order options into firm contracts and solidifying its medium-term fleet plan.","kImp":"옵션의 본계약 전환은 조선소 슬롯·납기 확보 측면에서 의미가 크다.","eImp":"Firming options matters for securing yard slots and delivery schedules.","url":"https://www.seatrade-maritime.com/cargo/wilhelmsen-upsizes-and-firms-car-carrier-options"}]},{"code":"EE","type":"news","kTitle":"Section 6. Energy Efficiency","eTitle":"Section 6. Energy Efficiency","items":[{"code":"EE-1","title":"World Fuel Services·West Coast Clean Fuels, 美 메탄올 벙커링 구축","src":"The Maritime Executive","date":"2026","kSum":"World Fuel Services가 West Coast Clean Fuels와 협력해 미국 항만에서 선주·운영사가 이용할 수 있는 메탄올 벙커링 역량을 구축했다. 남부 플로리다에서 해상 메탄올 벙커링을 성공적으로 완료했다.","eSum":"World Fuel Services, with West Coast Clean Fuels, established methanol bunkering available to owners/operators across US ports, completing an over-the-water methanol bunker delivery in South Florida.","kImp":"메탄올 벙커링 인프라 확산은 대체연료 선대 운용의 현실성을 높인다.","eImp":"Spreading methanol bunkering infrastructure makes alt-fuel fleet operation more viable.","url":"https://maritime-executive.com/corporate/world-fuel-services-west-coast-clean-fuels-establish-methanol-bunkering"},{"code":"EE-2","title":"컨테이너선이 대체연료 채택을 견인","src":"Seatrade Maritime","date":"2026","kSum":"컨테이너선 부문이 대체연료 채택을 주도하고 있다. 메탄올·암모니아 이중연료 신조·개조 수요가 늘며 연료 전환 속도가 빨라지고 있다.","eSum":"Container ships are driving alternative fuel adoption, with rising methanol/ammonia dual-fuel newbuild and retrofit demand accelerating the fuel transition.","kImp":"연료 전환 가속은 벙커링 인프라·연료 가용성·가격 헤지 전략을 요구한다.","eImp":"Faster transition demands bunkering infrastructure, fuel availability and price-hedging strategy.","url":"https://www.seatrade-maritime.com/sustainability-green-technology/container-ships-drive-alternative-fuel-adoption"},{"code":"EE-3","title":"첫 Kamsarmax 메탄올 추진 벌크선, Cargill 용선 인도","src":"The Maritime Executive","date":"2026","kSum":"세계 첫 메탄올 추진 Kamsarmax 벌크선이 Cargill 용선용으로 인도됐다. 벌크 부문에서도 메탄올 추진이 상업적 현실로 진입하고 있다.","eSum":"The first Kamsarmax methanol-fuelled bulker was delivered for Cargill charter, marking methanol propulsion entering commercial reality in the bulk sector.","kImp":"메탄올 추진이 컨테이너를 넘어 벌크로 확산되며 선종별 채택이 다변화된다.","eImp":"Methanol propulsion is spreading beyond boxships into bulk, diversifying adoption.","url":"https://maritime-executive.com/article/first-kamsarmax-methanol-fueled-bulker-delivered-for-cargill-charter"},{"code":"EE-4","title":"BV, Union Maritime 풍력보조·메탄올레디 탱커 시리즈 선급","src":"Seatrade Maritime","date":"2026","kSum":"Bureau Veritas가 Union Maritime의 메탄올레디 유류·케미컬 탱커 시리즈를 선급한다. Norsepower 로터세일 등 풍력보조 추진을 탑재하며 2026~2028년 25척 이상 인도 예정이다.","eSum":"Bureau Veritas is classing a series of methanol-ready oil/chemical tankers for Union Maritime fitted with wind propulsion including Norsepower Rotor Sails, with 25+ vessels due in 2026-2028.","kImp":"풍력보조+메탄올레디 조합이 탱커 신조의 탈탄소 표준으로 부상하고 있다.","eImp":"Wind-assist plus methanol-ready is emerging as a tanker newbuild decarbonisation standard.","url":"https://www.seatrade-maritime.com/wind-powered-ships/bv-to-class-union-maritime-wind-assisted-methanol-ready-tankers"},{"code":"EE-5","title":"세계 첫 메탄올 이중연료 Kamsarmax 벌크선 인도","src":"Marine Insight","date":"2026","kSum":"세계 최초의 메탄올 이중연료 Kamsarmax 벌크선이 인도됐다. 친환경 연료 추진의 벌크 부문 확산을 상징하는 이정표다.","eSum":"The world's first methanol dual-fuel Kamsarmax bulk carrier was delivered, a milestone for green-fuel propulsion spreading into the bulk segment.","kImp":"벌크 부문 대체연료 인도 본격화로 화주의 그린 수송 옵션이 넓어진다.","eImp":"Alt-fuel bulk deliveries broaden shippers' green-transport options.","url":"https://www.marineinsight.com/shipping-news/worlds-first-methanol-dual-fuel-kamsarmax-bulk-carrier-delivered/"},{"code":"EE-6","title":"X-Press Feeders, 첫 개조 메탄올 이중연료 컨테이너선 인수","src":"Seatrade Maritime","date":"2026","kSum":"X-Press Feeders가 첫 개조(retrofit) 메탄올 이중연료 컨테이너선을 인수했다. 기존선 개조를 통한 연료 전환이 현실적 대안으로 자리잡고 있다.","eSum":"X-Press Feeders received its first retrofitted dual-fuel methanol container ship, establishing retrofit as a practical route to fuel transition for existing tonnage.","kImp":"개조 경로는 신조 슬롯 부족 환경에서 단기 탈탄소 수단으로 유효하다.","eImp":"Retrofitting offers a near-term decarbonisation lever amid tight newbuild slots.","url":"https://www.seatrade-maritime.com/sustainability/x-press-feeders-receives-first-retrofitted-dual-fuel-methanol-container-ship"},{"code":"EE-7","title":"Exmar, 세계 첫 암모니아 이중연료 가스선 인도로 상용화","src":"Splash 247","date":"2026","kSum":"Exmar가 HD현대중공업이 건조한 46,000㎥급 가스운반선 'Antwerpen'을 인도받으며 암모니아 추진을 상용 현실로 끌어올렸다. WinGD 엔진을 탑재해 저탄소 암모니아 연료 시 기존선 대비 GHG를 최대 90% 저감한다.","eSum":"Ammonia propulsion reached commercial reality with Exmar's delivery of the 46,000-cu m gas carrier Antwerpen, built by HD Hyundai Heavy Industries with a WinGD engine, cutting GHG by up to 90% on low-carbon ammonia.","kImp":"암모니아 추진 상용화는 무탄소 연료 로드맵의 핵심 진전이다.","eImp":"Commercial ammonia propulsion is a key step on the zero-carbon fuel roadmap.","url":"https://splash247.com/ammonia-propulsion-reaches-commercial-reality-with-exmar-delivery/"}]},{"code":"DIG","type":"news","kTitle":"Section 7. Digitalization","eTitle":"Section 7. Digitalization","items":[{"code":"DIG-1","title":"AI 기술이 해운 사이버공격 위험을 키운다 — 신규 데이터","src":"Hellenic Shipping News","date":"2026","kSum":"AI 도입 가속이 해운 사이버공격 위험을 키우고 있다는 새 데이터가 공개됐다. 조직의 87%가 AI 관련 취약점을 가장 빠르게 증가하는 위험으로 인식하나, 사이버 책임체계 정의는 도입 속도를 따라가지 못하고 있다.","eSum":"New data shows AI is placing the maritime industry at greater cyber-attack risk. 87% of organisations view AI-related vulnerabilities as the fastest-growing risk, yet cyber accountability lags behind deployment.","kImp":"AI 자산 보호와 OT/IT 사이버 거버넌스(IMO 2021)를 우선 강화해야 한다.","eImp":"Prioritise AI-asset protection and OT/IT cyber governance (IMO 2021).","url":"https://www.hellenicshippingnews.com/ai-technology-is-placing-the-maritime-industry-at-greater-risk-of-a-cyber-attack-reveals-new-data/"},{"code":"DIG-2","title":"China 해운, 지능화로의 전환 가속","src":"Hellenic Shipping News","date":"2026","kSum":"중국 해운산업이 지능화(intelligence)로의 전환을 가속하고 있다. 이미 60개 자동화 컨테이너·벌크 터미널을 구축했으며, 1만톤 이상 선석의 약 28%가 자동화 선석이다.","eSum":"China's shipping industry is propelling a shift toward intelligence, having already built 60 automated container and dry-bulk terminals, with automated berths accounting for about 28% of those over 10,000 tonnes.","kImp":"스마트포트 확산은 입항선의 자동화 인터페이스·데이터 연계 대응을 요구한다.","eImp":"Smart-port growth requires calling vessels to support automation interfaces and data exchange.","url":"https://www.hellenicshippingnews.com/chinas-shipping-industry-propels-shift-toward-intelligence/"},{"code":"DIG-3","type":"news","title":"\"2026년은 해운 디지털화 돌파의 해\" — Smart Ship Hub","src":"Hellenic Shipping News","date":"2026-06","kSum":"Smart Ship Hub는 2026년이 해운 디지털화의 돌파(breakthrough) 해가 될 것이라고 전망했다. 저비용 엣지 게이트웨이·플러그앤플레이 센서로 노후선까지 광범위한 레트로핏이 가능해지고, 기관 데이터·영상·진동 모니터링을 통합한 실시간 선대 관제가 확산될 전망이다.","eSum":"Smart Ship Hub expects 2026 to be a breakthrough year for maritime digitalisation, with low-cost edge gateways and plug-and-play sensors enabling wide-scale retrofit on older vessels and unified platforms combining machinery data, video and vibration monitoring for real-time fleet awareness.","kImp":"저비용 레트로핏 디지털화는 노후선 운영효율·예지정비 도입의 문턱을 낮춘다.","eImp":"Low-cost retrofit digitalisation lowers the barrier to efficiency gains and predictive maintenance on older ships.","url":"https://www.hellenicshippingnews.com/maritime-industry-can-expect-a-breakthrough-year-in-2026-for-digitalisation-says-smart-ship-hub/"},{"code":"DIG-4","type":"news","title":"ABS 보고서: AI·디지털화·신에너지의 확산","src":"The Maritime Executive","date":"2026","kSum":"선급 ABS의 보고서는 AI·디지털화·신에너지가 해운 전반에 본격적으로 자리잡고 있음을 보여줬다. 데이터 기반 운영과 대체연료 전환이 동시에 진행되며 의사결정 체계가 재편되고 있다.","eSum":"An ABS report shows how AI, digitalization and new energy are taking hold across shipping, with data-driven operations and the alternative-fuel transition jointly reshaping decision-making.","kImp":"데이터·연료 전환의 동시 진행은 통합 디지털·컴플라이언스 역량을 요구한다.","eImp":"Parallel data and fuel transitions require integrated digital and compliance capability.","url":"https://maritime-executive.com/corporate/abs-report-shows-how-ai-digitalization-and-new-energy-are-taking-hold"}]},{"code":"TECH","type":"news","kTitle":"Section 8. Ship Manager Technical Team","eTitle":"Section 8. Ship Manager Technical Team","items":[{"code":"TECH-1","title":"DNV, 운항 중 선급(In-Operation) 프레임워크·수소선 규칙 신설","src":"The Maritime Executive","date":"2026","kSum":"DNV가 운항 중 선급(In-Operation Class) 프레임워크를 도입하고 수소 추진선을 가능케 하는 규칙을 신설했다. 설계·운항 요건이 혼재된 표기의 책임을 명확히 한다.","eSum":"DNV introduced an in-operation class framework and rules enabling hydrogen vessels, clarifying responsibilities for notations mixing design and operational requirements.","kImp":"운항 중 선급 책임범위 변화에 맞춰 기술팀의 표기·증빙 관리가 필요하다.","eImp":"Technical teams must align notation/evidence management with the in-operation class shift.","url":"https://maritime-executive.com/corporate/dnv-rules-create-in-operation-class-framework-enable-hydrogen-vessels"},{"code":"TECH-2","title":"DNV, 선박·해양구조물 선급 규칙 업데이트","src":"MarineLink","date":"2026","kSum":"DNV가 선박 및 해양구조물에 대한 선급 규칙을 업데이트했다. 탈탄소 기술(수소·OCCS 등) 적용을 지원하는 신규 표기가 포함됐다.","eSum":"DNV updated its class rules for ships and offshore structures, including new notations supporting decarbonisation technologies such as hydrogen and onboard carbon capture.","kImp":"신규 표기 도입 시 PMS·도면·기술사양의 선급 승인 절차를 재점검해야 한다.","eImp":"Review PMS, drawings and class-approval workflows for the new notations.","url":"https://www.marinelink.com/news/dnv-updates-class-rules-ships-offshore-515110"}]},{"code":"HR","type":"news","kTitle":"Section 9. Marine HR","eTitle":"Section 9. Marine HR","items":[{"code":"HR-1","title":"ITF, 25만 선원 임금 인상 확보 — 4.5% 인상","src":"The Maritime Executive","date":"2026","kSum":"ITF가 25만 명 선원에 대한 임금 인상을 확보했다. IBF 협약에 따라 향후 2년간 약 6%(연 4.5% 수준) 인상과 함께 폭력·차별·괴롭힘 없는 안전한 일터 보장이 포함됐다.","eSum":"The ITF secured a pay increase for 250,000 seafarers, with the IBF agreement providing about 6% over two years (a 4.5% raise) plus a joint commitment to a workplace free of violence, discrimination and harassment.","kImp":"선원 인건비 상승은 운항원가에 반영되며 인력 확보 경쟁이 심화된다.","eImp":"Higher seafarer costs feed into opex as competition for crew intensifies.","url":"https://maritime-executive.com/article/itf-secures-pay-increase-for-250-000-seafarers"},{"code":"HR-2","title":"선원 4.5% 임금인상 — ITF-사용자 합의","src":"The Maritime Executive","date":"2026","kSum":"ITF와 사용자측 합의에 따라 선원들이 4.5% 임금 인상을 받게 됐다. 임금 외에 폭력·차별·괴롭힘 없는 안전한 일터 보장도 포함됐다.","eSum":"Seafarers will receive a 4.5% pay increase under an ITF-employer agreement that also includes commitments to a workplace free of violence, discrimination and harassment.","kImp":"임금 인상 합의는 인건비 상승과 함께 선원 유지·확보에 긍정적이다.","eImp":"The pay deal lifts costs but aids crew retention and recruitment.","url":"https://maritime-executive.com/article/seafarers-to-receive-4-5-pay-increase-under-itf-employer-agreement"},{"code":"HR-3","title":"25만 선원 4년 협약 — 임금·일터 보호 강화","src":"gCaptain","date":"2026","kSum":"25만 명 선원을 대상으로 한 4년 협약이 임금 인상과 일터 보호 강화를 담았다. 신기술·그린연료·피로·승선기간 등 현안을 모니터링할 신규 위원회 설치가 합의됐다.","eSum":"A four-year agreement increases wages and workplace protections for 250,000 seafarers, with a new committee to monitor issues including new technology, green fuels, fatigue and length of service.","kImp":"장기 협약은 인건비 예측가능성을 높이고 노사 현안 관리 체계를 제도화한다.","eImp":"A multi-year deal improves cost predictability and institutionalises issue management.","url":"https://gcaptain.com/four-year-agreement-increases-wages-and-workplace-protections-for-250000-seafarers/"},{"code":"HR-4","title":"선원 4.5% 임금 인상 확정","src":"Splash 247","date":"2026","kSum":"선원 임금이 4.5% 인상으로 확정됐다. 숙련 인력 부족 속에서 임금 상승이 이어지고 있다.","eSum":"Seafarers landed a 4.5% pay raise, continuing wage growth amid a shortage of skilled crew.","kImp":"지속적 임금 상승은 운항원가 압박과 인력 확보 경쟁을 동시에 키운다.","eImp":"Continued wage growth raises opex pressure and competition for crew.","url":"https://splash247.com/seafarers-land-4-5-pay-raise/"},{"code":"HR-5","title":"ITF, 3년간 미지급 임금 1.2억 달러 회수","src":"Seatrade Maritime","date":"2026","kSum":"ITF가 지난 3년간 선원 미지급 임금 약 1억2천만 달러를 회수했다고 밝혔다. 임금 체불·선원 유기 문제가 여전히 심각함을 보여준다.","eSum":"The ITF recovered nearly USD 120 million in unpaid seafarer wages over three years, underlining that wage default and abandonment remain serious problems.","kImp":"임금 체불·유기 리스크 관리는 선사 평판·MLC 준수의 핵심 과제다.","eImp":"Managing wage-default and abandonment risk is key to reputation and MLC compliance.","url":"https://www.seatrade-maritime.com/crewing/itf-recovers-nearly-120-million-in-unpaid-seafarer-wages-over-3-years"},{"code":"HR-6","title":"ITF: 선원 임금 위반 사례 증가","src":"The Maritime Executive","date":"2026","kSum":"ITF는 선원 임금 위반(wage violations) 사례가 증가하고 있다고 경고했다. 임금 미지급·부분지급·지연지급 사례가 늘며 점검·집행이 강화되고 있다.","eSum":"The ITF warned that seafarer wage violations are on the rise, with more cases of non-, partial- and late payment prompting tighter scrutiny and enforcement.","kImp":"임금 지급 적정성 관리가 노무 리스크·선원 신뢰 유지의 전제 조건이다.","eImp":"Proper wage administration is a precondition for managing labour risk and crew trust.","url":"https://maritime-executive.com/article/itf-seafarer-wage-violations-are-on-the-rise"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ (Health · Safety · Environment · Quality)","eTitle":"Section 10. HSEQ (Health · Safety · Environment · Quality)","items":[{"code":"HSEQ-1","title":"EU ETS 컴플라이언스의 복잡성","src":"Seatrade Maritime","date":"2026","kSum":"EU ETS 준수의 복잡성이 부각되고 있다. 책임주체(선주·관리자·나용선자)와 배출량 모니터링·검증·정산 절차의 정합성 확보가 과제다.","eSum":"The complexities of EU ETS compliance are coming to the fore, with challenges in aligning responsible entities (owner/manager/bareboat charterer) and emissions monitoring, verification and settlement.","kImp":"책임주체 명확화와 MRV 데이터 정확성이 분쟁·페널티 예방의 핵심이다.","eImp":"Clear responsibility allocation and accurate MRV data are key to avoiding disputes and penalties.","url":"https://www.seatrade-maritime.com/regulations/complexities-of-compliance-with-the-eu-emissions-trading-scheme"},{"code":"HSEQ-2","title":"FuelEU Maritime, 새로운 중대한 도전 예고","src":"Seatrade Maritime","date":"2026","kSum":"FuelEU Maritime이 새로운 중대한 도전을 제기할 것으로 전망됐다. 책임주체는 ISM(DOC) 회사이며, 2026년 4월부터 배출량이 본격 관리되고 첫 정산 사이클이 진행된다.","eSum":"FuelEU Maritime is set to pose significant new challenges. The responsible entity is the ISM (DoC) company, with emissions actively managed from April 2026 and the first compliance cycle playing out.","kImp":"ISM 회사로서의 FuelEU 책임을 SMS·연료관리 절차에 명확히 반영해야 한다.","eImp":"Embed FuelEU responsibility as the ISM company into SMS and fuel-management procedures.","url":"https://www.seatrade-maritime.com/regulations/fueleu-to-pose-significant-new-challenges"},{"code":"HSEQ-3","title":"선주, 신규 연료 규제 발효로 중대 과제 직면","src":"Seatrade Maritime","date":"2026","kSum":"신규 연료 규제(EU ETS·FuelEU) 발효로 선주들이 중대한 과제에 직면했다. 보고·검증·페널티가 2025년 실적에 대해 2026년 상반기에 집중된다.","eSum":"Shipowners face major challenges as new fuel regulations enter force, with reporting, verification and penalties for 2025 performance all landing in H1 2026.","kImp":"규제 중첩에 대비한 통합 컴플라이언스·데이터 관리 체계가 필요하다.","eImp":"Overlapping regulations call for integrated compliance and data-management systems.","url":"https://www.seatrade-maritime.com/regulations/shipowners-face-major-challenges-as-new-fuel-regulations-enter-force"},{"code":"HSEQ-4","title":"EU ETS·FuelEU — LNG 컴플라이언스의 '이중 배당'","src":"Hellenic Shipping News","date":"2026","kSum":"EU ETS와 FuelEU Maritime에서 LNG 컴플라이언스가 '이중 배당' 효과를 낸다는 분석이 나왔다. 두 규제의 상호작용을 활용한 연료·항로 최적화 전략이 비용을 좌우한다.","eSum":"Analysis points to a 'double dividend' of LNG compliance across EU ETS and FuelEU Maritime, where exploiting the interaction of the two regimes drives fuel and routing optimisation costs.","kImp":"규제 간 상호작용을 반영한 연료 선택·항로 전략이 컴플라이언스 비용을 좌우한다.","eImp":"Fuel choice and routing reflecting regime interactions determine compliance costs.","url":"https://www.hellenicshippingnews.com/eu-ets-and-fueleu-maritime-the-double-dividend-of-lng-compliance-in-2026/"},{"code":"HSEQ-5","title":"BIMCO, 선박 매매용 FuelEU·ETS 표준조항 발표","src":"Splash 247","date":"2026","kSum":"BIMCO가 선박 매매 거래용 FuelEU·ETS 표준조항(클로즈)을 새로 내놓았다. 배출권·페널티 책임의 거래 당사자 간 배분을 명확히 하기 위한 계약 표준화다.","eSum":"BIMCO rolled out new FuelEU and ETS clauses for ship sale deals, standardising contracts to clarify allocation of allowance and penalty liabilities between parties.","kImp":"표준조항 채택으로 매매·용선 계약의 배출 책임 분쟁 위험을 줄일 수 있다.","eImp":"Adopting standard clauses reduces emissions-liability disputes in sale and charter deals.","url":"https://splash247.com/bimco-rolls-out-new-fueleu-and-ets-clauses-for-ship-sale-deals/"}]},{"code":"KR","type":"news","kTitle":"Section 11. 한국해운 시장 (Korean Shipping Market)","eTitle":"Section 11. Korean Shipping Market","items":[{"code":"KR-1","title":"HMM, 2026년 연간 영업이익 전년比 38% 감소 8,580억원 전망","src":"쉬핑뉴스넷 (Shipping News Net)","date":"2026","kSum":"HMM(에이치엠엠)의 2026년 연간 영업이익이 전년 대비 38% 감소한 8,580억원으로 전망됐다. 운임 정상화와 선복 공급 증가가 수익성에 부담으로 작용하고 있다.","eSum":"HMM's 2026 annual operating profit is forecast at KRW 858bn, down 38% year-on-year, as freight normalisation and rising capacity weigh on profitability.","kImp":"운임 하락 국면에서 HMM의 비용효율·매각 이슈가 핵심 변수로 부각된다.","eImp":"In a softening freight market, HMM's cost efficiency and privatisation become key variables.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=68752"},{"code":"KR-2","title":"팬오션(Pan Ocean)·HMM, 첫 '해운의 탑' 수상","src":"해양수산부 (MOF)","date":"2026","kSum":"해양수산부(MOF)가 팬오션(Pan Ocean)·HMM 등에 첫 '해운의 탑'을 수여했다. 해운 수출·외화가득 기여 기업을 포상하는 제도로 한국 해운의 위상을 부각했다.","eSum":"Korea's Ministry of Oceans and Fisheries awarded the first 'Shipping Tower' to Pan Ocean, HMM and others, recognising firms' contribution to shipping exports and foreign-currency earnings.","kImp":"정부 포상제도는 해운산업 진흥 의지를 보여주며 정책 지원 기대를 높인다.","eImp":"The government award signals intent to promote shipping and raises policy-support expectations.","url":"https://mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=52016&menuSeq=971"},{"code":"KR-3","title":"프리미어얼라이언스, 부산항 뱃길 4편 증편 — 북미·유럽 강화","src":"코리아쉬핑가제트 (KSG)","date":"2026","kSum":"프리미어얼라이언스가 부산항 기항 서비스를 4편 늘려 북미·유럽 노선을 강화했다. 환적 허브로서 부산항의 경쟁력 제고가 기대된다.","eSum":"The Premier Alliance added four services calling Busan, strengthening North America and Europe routes and bolstering Busan's competitiveness as a transhipment hub.","kImp":"기항 증편은 부산항 환적물동량 확대와 항만 경쟁력에 긍정적이다.","eImp":"More calls support Busan's transhipment volumes and port competitiveness.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=146144"},{"code":"KR-4","title":"CJ대한통운·팬오션·대한해운 52주 신고가…현대글로비스 급등","src":"쉬핑뉴스넷 (Shipping News Net)","date":"2026","kSum":"지난 한 달간 CJ대한통운·팬오션(Pan Ocean)·대한해운(Korea Line)이 52주 신고가를 경신하고 현대글로비스(Hyundai Glovis) 주가가 급등하는 등 물류·해운주 랠리가 나타났다.","eSum":"Over the past month CJ Logistics, Pan Ocean and Korea Line hit 52-week highs and Hyundai Glovis surged, marking a rally across logistics and shipping equities.","kImp":"해운·물류주 강세는 업황 기대와 전방산업 회복 신호로 해석된다.","eImp":"Strength in shipping/logistics equities reflects sector optimism and downstream recovery.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=68536"},{"code":"KR-5","title":"'가스공사 전용선 30% 점유' 현대LNG해운 해외매각 논란","src":"코리아쉬핑가제트 (KSG)","date":"2026","kSum":"한국가스공사 전용선의 약 30%를 점유하는 현대LNG해운(Hyundai LNG Shipping)의 해외매각을 두고 논란이 일고 있다. 국가전략물자 수송선대의 해외 매각에 대한 우려가 제기된다.","eSum":"The overseas sale of Hyundai LNG Shipping, which holds about 30% of KOGAS dedicated carriers, has stirred controversy over selling a strategically important national fleet abroad.","kImp":"전략물자 수송선대의 소유구조 변화는 에너지안보 차원의 검토가 필요하다.","eImp":"Ownership changes of strategic-cargo fleets warrant energy-security scrutiny.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=146022"},{"code":"KR-6","title":"아비커스(Avikus), HMM 선대에 자율운항 솔루션 공급","src":"한국해운신문 (Maritime Press)","date":"2026","kSum":"HD현대 자회사 아비커스(Avikus)가 HMM 선대에 자율운항 솔루션을 공급한다. 한국 선사·기술기업 간 자율운항 상용화 협력이 본격화되고 있다.","eSum":"Avikus, an HD Hyundai unit, will supply autonomous navigation solutions to HMM's fleet, advancing commercialisation cooperation between Korean operators and technology firms.","kImp":"국산 자율운항 기술의 상선 적용 확대는 K-조선·해운의 디지털 경쟁력을 높인다.","eImp":"Wider deployment of Korean autonomous tech strengthens K-shipbuilding/shipping digital competitiveness.","url":"http://www.maritimepress.co.kr/news/articleView.html?idxno=329629"},{"code":"KR-7","title":"삼성중공업(Samsung Heavy), '축구장 4개 규모' 부유식 LNG생산설비 진수","src":"코리아쉬핑가제트 (KSG)","date":"2026","kSum":"삼성중공업(Samsung Heavy Industries)이 축구장 4개 규모의 부유식 LNG생산설비(FLNG)를 진수했다. 고부가가치 해양플랜트 분야에서 한국 조선의 경쟁력을 입증했다.","eSum":"Samsung Heavy Industries launched a floating LNG production facility (FLNG) the size of four football pitches, demonstrating Korea's competitiveness in high-value offshore plants.","kImp":"FLNG 등 해양플랜트 수주 확대는 조선 3사 실적 다변화에 기여한다.","eImp":"Growth in FLNG/offshore orders diversifies the big-three shipbuilders' earnings.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=146368"},{"code":"KR-8","title":"한화오션(Hanwha Ocean), 2026년 특수선·해양플랜트 수주 주목","src":"쉬핑뉴스넷 (Shipping News Net)","date":"2026","kSum":"한화오션(Hanwha Ocean)은 2026년 특수선 및 해양플랜트 수주에 주목해야 하는 해로 평가됐다. 미국 특수선 테마와 해양 사업 확장이 수주 모멘텀으로 거론된다.","eSum":"Hanwha Ocean is seen as one to watch for naval/special-ship and offshore plant orders in 2026, with the US naval theme and offshore expansion cited as order momentum.","kImp":"특수선·방산 부문은 상선 사이클과 무관한 안정적 수익원으로 부상하고 있다.","eImp":"Naval/defence work is emerging as a stable earnings source decoupled from the merchant cycle.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=69948"}]},{"code":"INS","type":"news","kTitle":"Section 12. P&I · H&M 보험 (P&I & Hull/Machinery Insurance)","eTitle":"Section 12. P&I & Hull/Machinery Insurance","items":[{"code":"INS-1","title":"NorthStandard, Hull & War 담보 상품 안내","src":"NorthStandard","date":"2026","kSum":"NorthStandard가 선체·전쟁(Hull & War) 담보 상품을 안내했다. 선체·기계(H&M)와 전쟁위험을 결합한 담보 구조로 지정학 리스크 환경에서 보장공백을 줄이는 옵션을 제시했다.","eSum":"NorthStandard set out its Hull & War product, combining Hull & Machinery with war-risk cover to reduce coverage gaps in a heightened geopolitical-risk environment.","kImp":"H&M+전쟁위험 결합담보 검토로 걸프 등 고위험 운항의 보장공백을 방지할 수 있다.","eImp":"Combined H&M+war cover can close protection gaps for high-risk trades like the Gulf.","url":"https://north-standard.com/product-service/hull-war"},{"code":"INS-2","title":"NorthStandard, P&I 보험과 전쟁위험 보험의 상호작용 해설","src":"NorthStandard","date":"2026","kSum":"NorthStandard가 P&I 보험과 전쟁위험 보험의 상호작용을 해설했다. 충돌·전쟁 상황에서 어느 담보가 우선 적용되는지 명확히 이해하는 것이 클레임 처리의 관건이다.","eSum":"NorthStandard explained the interaction between P&I insurance and war-risk insurance, stressing that understanding which cover applies in collision/war scenarios is key to claims handling.","kImp":"담보 간 경계·우선순위 이해가 분쟁성 클레임 대응에 필수적이다.","eImp":"Understanding cover boundaries and priority is essential for handling contentious claims.","url":"https://north-standard.com/insights-and-resources/resources/articles/the-interaction-between-pi-insurance-and-war-risks-insurance"},{"code":"INS-3","title":"NorthStandard, 2026 정책연도 갱신 안내","src":"NorthStandard","date":"2026","kSum":"NorthStandard가 2026 정책연도(Policy Year) 갱신 안내를 발행했다. 클레임 동향·재보험 비용을 반영한 갱신 조건이 제시됐다.","eSum":"NorthStandard issued its Policy Year 2026 renewal circular, setting out renewal terms reflecting claims trends and reinsurance costs.","kImp":"갱신 조건·일반증액(General Increase) 동향을 예산·계약에 사전 반영해야 한다.","eImp":"Factor renewal terms and any general increase into budgets and contracts in advance.","url":"https://north-standard.com/insights-and-resources/resources/circulars/policy-year-2026-renewal-ref-001"},{"code":"INS-4","type":"news","title":"'다크 활동' 시대의 해상보험 난제 — 찾을 수 없는 선대 모니터링","src":"Hellenic Shipping News","date":"2026-06","kSum":"AIS를 끄는 '다크 활동(dark activity)'이 늘며 보험사가 추적할 수 없는 선대를 모니터링해야 하는 난제가 부각됐다. 제재·전쟁위험 환경에서 익스포저 파악과 인수심사가 어려워지고 있다.","eSum":"As 'dark activity' (AIS switched off) grows, insurers face the challenge of monitoring fleets they cannot find, making exposure assessment and underwriting harder in a sanctions/war-risk environment.","kImp":"다크 운항 확산은 보험 인수·요율·컴플라이언스 리스크를 동시에 키운다.","eImp":"Spreading dark operation simultaneously raises underwriting, pricing and compliance risk.","url":"https://www.hellenicshippingnews.com/monitoring-a-fleet-you-cant-find-the-marine-insurance-challenge-in-a-dark-activity-era/"},{"code":"INS-5","type":"news","title":"호르무즈, 해상 리스크 프리미엄, 그리고 공포","src":"Splash 247","date":"2026-06","kSum":"호르무즈 사태로 걸프행 선박의 선체전쟁위험 보험료가 선가의 1%(7일 담보)로 4배 급등했다. P&I 인터내셔널 그룹 12개 클럽이 72시간 통지로 일부 전쟁 담보를 취소하는 등 리스크 프리미엄과 공포가 시장을 지배하고 있다.","eSum":"The Hormuz crisis quadrupled hull-war premiums for Gulf-bound vessels to 1% of ship value for seven days' cover, while all 12 International Group P&I clubs cancelled certain war cover on 72-hour notice — risk premium and fear now dominate the market.","kImp":"전쟁위험료 급등·담보 취소는 걸프 운항의 채산성과 가능여부를 좌우한다.","eImp":"Surging war premiums and cover cancellations determine the economics and feasibility of Gulf trading.","url":"https://splash247.com/hormuz-the-maritime-risk-premium-and-fear/"},{"code":"INS-6","type":"news","title":"Owned Hull War Risks — 담보 취소 통지","src":"Hellenic Shipping News","date":"2026-06","kSum":"재보험사들이 이란·페르시아(아라비아)만에서 발생하는 전쟁위험 책임에 대해 담보 취소 통지를 발행했다. 특정 지리적 한도 내 모든 전쟁위험 클레임을 제외하는 새 문구가 적용된다.","eSum":"Reinsurers issued notices of cancellation for owned hull war risks arising in Iran and the Persian/Arabian Gulf, applying new wording that excludes all war-risk claims within specified geographical limits.","kImp":"담보 취소·제외 문구 적용으로 걸프 운항 전 추가담보 확보가 필수다.","eImp":"With cancellation/exclusion wording in force, additional cover must be secured before Gulf trading.","url":"https://www.hellenicshippingnews.com/owned-hull-war-risks-notice-of-cancellation/"},{"code":"INS-7","type":"news","title":"Steamship Mutual — 전쟁위험 담보 취소 통지","src":"Hellenic Shipping News","date":"2026-06","kSum":"Steamship Mutual이 전쟁위험(War Risks) 담보 취소 통지를 발행했다. 지역 분쟁 격화에 따라 회원사 대상 담보 조건·지리적 한도가 조정되고 있다.","eSum":"Steamship Mutual issued a War Risks notice of cancellation, adjusting cover terms and geographical limits for members as the regional conflict escalates.","kImp":"클럽별 담보 취소·갱신 조건을 즉시 확인해 보장공백을 방지해야 한다.","eImp":"Check each club's cancellation/renewal terms immediately to avoid coverage gaps.","url":"https://www.hellenicshippingnews.com/steamship-mutual-war-risks-notice-of-cancellation/"}]},{"code":"VET","type":"news","kTitle":"Section 13. RightShip · Vetting Inspection","eTitle":"Section 13. RightShip · Vetting Inspection","items":[{"code":"VET-1","title":"RightShip, 업계 반발에 벌크선 검사 변경 일부 연기","src":"Seatrade Maritime","date":"2026","kSum":"RightShip이 업계 반발(pushback)에 따라 건화물선 검사 제도 변경 일부를 연기했다. 선령 기준 강화 일정에 대한 선주·운영사들의 우려를 반영한 조치다.","eSum":"RightShip delayed some dry bulk inspection changes after industry pushback, reflecting owner/operator concerns over the accelerated age-trigger timeline.","kImp":"제도 변경 일정 변동을 모니터링해 검사 계획·예산을 유연하게 조정해야 한다.","eImp":"Monitor shifting timelines to keep inspection planning and budgets flexible.","url":"https://www.seatrade-maritime.com/dry-bulk/rightship-delays-dry-bulk-inspection-changes-after-industry-pushback"},{"code":"VET-2","title":"RightShip, 벌크선 연례검사 선령 기준 10년으로 단계 축소","src":"Seatrade Maritime","date":"2026","kSum":"RightShip이 벌크선 연례검사 적용 선령 기준을 10년으로 단계적으로 낮춘다. 사고·사망·PSC 억류율이 높은 건화물 부문의 안전 개선을 목표로 한다.","eSum":"RightShip is cutting the bulker annual-inspection age to 10 years in stages, aiming to improve safety in a dry bulk sector facing higher incident, fatality and PSC-detention rates.","kImp":"연례검사 대상 확대로 벌크선대의 검사 수검 부담과 준비 수요가 증가한다.","eImp":"A wider annual-inspection net raises the inspection-readiness burden across bulk fleets.","url":"https://www.seatrade-maritime.com/dry-bulk/rightship-cuts-bulker-annual-inspection-age-to-10-years"},{"code":"VET-3","title":"OCIMF, SIRE 2.0 신규 탱커 검사 프로그램 단계적 시행","src":"Hellenic Shipping News","date":"2026","kSum":"OCIMF가 기존 SIRE를 대체하는 디지털 탱커 검사 프로그램 SIRE 2.0의 단계적 시행에 들어갔다. 종이 질문지가 본질안전형 태블릿으로 대체되고, 과거 보고서 기반의 동적 질문세트가 도입됐다.","eSum":"OCIMF began the phased roll-out of SIRE 2.0, its digital tanker inspection programme replacing the legacy SIRE. Paper questionnaires are replaced by intrinsically safe tablets with dynamic question sets based on past reports.","kImp":"탱커 운영사는 SIRE 2.0 사전정보(PVIQ)·동적 질문 대응 체계를 정비해야 한다.","eImp":"Tanker operators must prepare for SIRE 2.0 pre-inspection data and dynamic questioning.","url":"https://www.hellenicshippingnews.com/ocimf-begins-phased-roll-out-of-new-sire-2-0-tanker-inspection-programme/"},{"code":"VET-4","title":"SIRE 2.0, '학습·개방 문화'로 탱커 부문 발전 견인","src":"SAFETY4SEA","date":"2026","kSum":"OCIMF는 SIRE 2.0이 학습·개방 문화를 통해 탱커 부문 발전을 견인하고 있다고 밝혔다. 출범 1년간 전 세계 탱커 선대에서 24,000건의 검사가 수행됐다.","eSum":"OCIMF says SIRE 2.0 shows how a culture of learning and openness can drive the tanker sector forward, with 24,000 inspections conducted across the global tanker fleet in its first year.","kImp":"검사 데이터 축적이 선사별 결함 추세·인적요인 관리 개선의 기회를 제공한다.","eImp":"Accumulated inspection data offers a chance to improve deficiency-trend and human-factor management.","url":"https://safety4sea.com/cm-ocimf-sire-2-0-shows-how-a-culture-of-learning-and-openness-can-drive-the-tanker-sector-forward/"},{"code":"VET-5","title":"OCIMF, SIRE 2.0 보안 강화 집중검사 캠페인(FIC) 시행","src":"MarineLink","date":"2026","kSum":"OCIMF가 SIRE 2.0 하에서 전 세계 탱커 선대의 해상보안 대비태세를 강화하기 위한 집중검사 캠페인(Focused Inspection Campaign)을 시행했다. 캠페인은 2025년 10월 1일 시작돼 최소 6개월간 진행된다.","eSum":"OCIMF launched a Focused Inspection Campaign under SIRE 2.0 to reinforce maritime security readiness across the global tanker fleet, commencing 1 October 2025 for a minimum of six months.","kImp":"보안 FIC 대상 탱커는 ISPS·보안훈련 증빙을 사전 점검해 지적을 예방해야 한다.","eImp":"Tankers in scope should pre-check ISPS/security-drill evidence to avoid observations.","url":"https://www.marinelink.com/news/ocimf-launches-focused-inspection-531728"},{"code":"VET-6","title":"OCIMF, 기존 SIRE 탱커 검사 프로그램 신 체제로 대체","src":"The Maritime Executive","date":"2026","kSum":"OCIMF가 기존 SIRE 탱커 검사 프로그램을 신규 체제(SIRE 2.0)로 대체했다. 더 포괄적인 검사 절차와 강화된 정책·절차가 핵심이다.","eSum":"OCIMF is replacing the legacy SIRE tanker inspection programme with the new SIRE 2.0 regime, centred on a more comprehensive inspection process and enhanced policies and procedures.","kImp":"신 체제 전환에 맞춰 SMS·검사대응 매뉴얼을 SIRE 2.0 기준으로 갱신해야 한다.","eImp":"Update SMS and inspection-response manuals to SIRE 2.0 standards for the transition.","url":"https://maritime-executive.com/corporate/ocimf-replacing-sire-tanker-inspection-programme-with-new-regime"},{"code":"VET-7","title":"OCIMF, SIRE 2.0 차량 검사 체제 단계적 시행 확정","src":"Hellenic Shipping News","date":"2026","kSum":"OCIMF가 SIRE 2.0 선박 검사 체제의 단계적 시행 일정을 확정했다. 운영사는 검사관 도착 전 선박 제원·정보를 사전 제공할 수 있어 준비 효율이 높아진다.","eSum":"OCIMF confirmed the phased roll-out schedule for the SIRE 2.0 vessel inspection regime, letting operators supply vessel particulars and information ahead of the inspector's arrival to improve preparation.","kImp":"사전정보 제공 절차를 표준화해 검사 준비 리드타임을 단축해야 한다.","eImp":"Standardise pre-inspection data submission to shorten inspection-preparation lead time.","url":"https://www.hellenicshippingnews.com/phased-roll-out-for-ocimfs-sire-2-0-vessel-inspection-regime/"}]},{"code":"CLASS","type":"news","kTitle":"Section 14. 주요 선급 뉴스 (Classification Societies)","eTitle":"Section 14. Classification Societies","items":[{"code":"CLASS-1","title":"IACS, 암모니아 연료 안전 신규 통일규칙(UR) 채택","src":"MarineLink","date":"2026","kSum":"국제선급연합회(IACS)가 암모니아 연료 시스템의 누출·안전에 관한 신규 통일규칙(UR)을 채택했다. UR M78 개정 등으로 암모니아를 승인 연료로 포함하는 안전요건이 확대됐다. KR·DNV·NK·BV 등 회원 선급이 공통 적용한다.","eSum":"IACS adopted a new Unified Requirement covering ammonia release and safety for onboard fuel systems, expanding safety requirements to include ammonia as an approved fuel (e.g. UR M78 revision). Member societies KR, DNV, ClassNK and BV apply it in common.","kImp":"암모니아 추진 신조·개조 시 IACS UR 기반 설계·승인 체계를 사전 반영해야 한다.","eImp":"Ammonia newbuild/retrofit designs must align with IACS UR-based approval from the outset.","url":"https://www.marinelink.com/news/iacs-adopts-new-unified-requirement-510921"},{"code":"CLASS-2","title":"IACS UR E26·E27 적용선 인도 단계 진입 — 보안품질·비용 과제","src":"Hellenic Shipping News","date":"2026","kSum":"2024년 7월 이후 계약된 신조선에 적용된 IACS 사이버복원력 통일규칙 UR E26(선박)·E27(기자재)을 충족한 선박들이 인도 단계에 들어섰다. '규칙 충족'을 넘어 보안 품질과 비용 절감이 새로운 과제로 부상했다. 한국선급(KR)은 K조선·ForceTEC 등에 E26 기반 AiP를 부여했다.","eSum":"Ships meeting IACS cyber-resilience URs E26 (ships) and E27 (equipment) — applied to newbuilds contracted from July 2024 — are now entering delivery; beyond mere compliance, security quality and cost savings emerge as challenges. Korean Register (KR) has granted E26-based AiPs (e.g. to K Shipbuilding and ForceTEC).","kImp":"E26·E27 인도선의 사이버 보안 검증·유지관리를 기술팀·선급과 사전 정렬해야 한다.","eImp":"Align cyber-security verification and upkeep of E26/E27 deliveries with technical teams and class early.","url":"https://www.hellenicshippingnews.com/as-ships-under-iacs-ur-e26%C2%B7e27-enter-the-delivery-stage-beyond-meeting-the-rules-ship-security-quality-and-cost-savings-emerge-as-the-challenge/"},{"code":"CLASS-3","title":"ClassNK(NK), 사이버 복원력 5대 요소 분석 발표","src":"SAFETY4SEA","date":"2026","kSum":"일본선급 ClassNK(NK)가 선박 사이버 복원력의 5대 요소를 정리해 발표했다. 식별·방어·탐지·대응·복구 체계를 통한 OT/IT 위험 관리 가이드를 제시했다.","eSum":"ClassNK (NK) published an analysis of the five elements of cyber resilience, offering guidance on managing OT/IT risk through identify, protect, detect, respond and recover.","kImp":"선급 사이버 가이드를 SMS·기자재 유지보수 절차에 반영해 복원력을 높여야 한다.","eImp":"Embed class cyber guidance into SMS and equipment maintenance to raise resilience.","url":"https://safety4sea.com/classnk-explores-the-five-elements-of-cyber-resilience/"},{"code":"CLASS-4","title":"주요 선급들, 배출량 데이터 표준 공동 추진","src":"SAFETY4SEA","date":"2026","kSum":"DNV·BV·NK 등 주요 선급들이 선박 배출량 데이터의 표준화를 위해 공동 추진에 나섰다. EU ETS·FuelEU·CII 등 규제 보고를 위한 데이터 정합성·상호운용성 제고가 목표다.","eSum":"Major class societies (DNV, BV, NK and others) are joining forces on an emissions data standard, aiming to improve data consistency and interoperability for EU ETS, FuelEU and CII reporting.","kImp":"배출 데이터 표준화는 규제 보고 부담을 줄이고 MRV 정확도를 높인다.","eImp":"An emissions data standard cuts reporting burden and improves MRV accuracy.","url":"https://safety4sea.com/class-societies-join-forces-for-emissions-data-standard/"},{"code":"CLASS-5","title":"IACS, 사이버 안전 통일규칙(E26·E27) 강화","src":"MarineLink","date":"2026","kSum":"IACS가 사이버 안전 통일규칙(UR E26·E27)을 강화했다. 신조선의 OT/IT 사이버 복원력 최소요건이 상향되며 조선소·기자재 공급망의 대응이 요구된다.","eSum":"IACS enhanced its cyber-safety Unified Requirements (UR E26/E27), raising minimum OT/IT cyber-resilience requirements for newbuilds and demanding action across yards and the equipment supply chain.","kImp":"강화된 사이버 UR은 신조 사양·검사 항목에 즉시 반영해야 한다.","eImp":"Tightened cyber URs must be reflected in newbuild specs and survey scope now.","url":"https://www.marinelink.com/news/iacs-enhances-cyber-safety-unified-508443"},{"code":"CLASS-6","title":"조선소·기자재 업계, 다가오는 IACS 사이버보안 요건 신속 대응 필요","src":"Hellenic Shipping News","date":"2026","kSum":"조선소와 기자재 공급업체가 다가오는 IACS 사이버보안 요건(UR E26·E27)에 신속히 대응해야 한다는 진단이 나왔다. 설계·통합·시험 단계의 사전 준비가 인도 지연·비용 증가를 좌우한다.","eSum":"Yards and vendors must act promptly to comply with upcoming IACS cyber-security requirements (UR E26/E27); early preparation in design, integration and testing will determine delivery delays and cost.","kImp":"공급망 전반의 사이버 요건 준비 상태를 신조 계약·감독 단계에서 점검해야 한다.","eImp":"Check supply-chain cyber-readiness during newbuild contracting and supervision.","url":"https://www.hellenicshippingnews.com/yards-and-vendors-must-act-promptly-to-comply-with-upcoming-iacs-cyber-security-requirements/"},{"code":"CLASS-7","type":"news","title":"한국선급(KR), LNG·암모니아 벙커링선 설계 승인","src":"SAFETY4SEA","date":"2026","kSum":"한국선급(Korean Register, KR)이 LNG 벙커링선과 암모니아 벙커링선에 대한 승인을 부여했다. 대체연료 공급 인프라 선박의 설계 안전성을 검증해 친환경 벙커링 생태계 구축을 뒷받침한다.","eSum":"Korean Register (KR) approved an LNG bunkering vessel and an ammonia bunkering vessel, verifying the design safety of alternative-fuel supply ships and supporting the build-out of a green bunkering ecosystem.","kImp":"벙커링선 승인은 암모니아·LNG 연료 공급망 구축의 핵심 인프라 진전이다.","eImp":"Bunkering-vessel approvals advance the critical infrastructure for ammonia/LNG fuel supply.","url":"https://safety4sea.com/kr-approves-an-lng-and-an-ammonia-bunkering-vessel/"},{"code":"CLASS-8","type":"news","title":"한국선급(KR), 삼성중공업 9,300 TEU 암모니아 연료 컨테이너선 설계 승인","src":"MarineLink","date":"2026","kSum":"한국선급(KR)이 삼성중공업(Samsung Heavy Industries)의 9,300 TEU급 암모니아 연료 컨테이너선 설계를 승인(AiP)했다. 암모니아 추진 상선 상용화를 향한 한국 선급·조선의 기술 진전을 보여준다.","eSum":"Korean Register (KR) granted approval (AiP) for Samsung Heavy Industries' 9,300-TEU ammonia-fuelled container ship design, marking progress by Korean class and shipbuilders toward commercial ammonia-fuelled merchant ships.","kImp":"대형 암모니아 컨테이너선 설계 승인은 무탄소 추진 상용화 로드맵의 진전이다.","eImp":"Approval of a large ammonia container-ship design advances the zero-carbon propulsion roadmap.","url":"https://www.marinelink.com/news/kr-approves-design-shis-teu-ammoniafueled-517186"}]},{"code":"COMM","type":"news","kTitle":"Section 15. Commercial · 용선시장 (Chartering Market: PCTC·Tanker·Bulk)","eTitle":"Section 15. Commercial / Chartering Market","items":[{"code":"COMM-1","title":"VLCC 일일 운임 사상 최고 — $424,000/day","src":"The Maritime Executive","date":"2026-06","kSum":"초대형원유운반선(VLCC) 일일 운임이 사상 최고치인 약 $424,000/day로 치솟았다. Baltic Exchange의 MEG-China(TD3C) 지수가 기록적 수준에 도달했으며, 호르무즈 지정학 리스크에 따른 선복 기피·물량 쏠림이 원인이다.","eSum":"VLCC spot earnings hit a record near $424,000/day, with the Baltic Exchange MEG-China (TD3C) index reaching extraordinary levels driven by Hormuz geopolitical risk, vessel avoidance and cargo concentration.","kImp":"탱커 스팟 운임 급등은 선주 수익 급증과 동시에 변동성·운임 리스크 관리 필요성을 키운다.","eImp":"Soaring tanker spot rates boost owner earnings but heighten volatility and rate-risk management needs.","url":"https://maritime-executive.com/article/vlcc-rates-hit-new-sky-high-record-424-000-per-day"},{"code":"COMM-2","title":"원유 탱커 운임 '미지의 영역'…VLCC 지수 $420K 돌파","src":"Lloyd's List","date":"2026-06","kSum":"원유 탱커 운임이 전례 없는 수준에 진입하며 VLCC 지수가 $420,000/day를 넘어섰다. 지정학 리스크와 항로 재편이 운임을 끌어올리고 있다.","eSum":"Crude tanker rates entered uncharted territory with the VLCC index topping $420K/day, as geopolitical risk and route rewiring push rates higher.","kImp":"초고운임 국면은 단기 수익 기회이자 화주·운영사의 운임 헤지 부담을 동반한다.","eImp":"Ultra-high rates offer short-term upside but burden charterers/operators with hedging needs.","url":"https://www.lloydslist.com/LL1156492/Crude-tanker-rates-in-unchartered-territory-VLCC-index-tops-420K"},{"code":"COMM-3","title":"PCTC 용선료 인상 확인 — Gram Car Carriers","src":"Lloyd's List","date":"2026","kSum":"Gram Car Carriers가 PCTC(자동차운반선) 용선료 인상을 확인했다. 6,500 CEU급 1년 정기용선료가 약 $105,000/day 수준으로, 자동차운반선이 수년간 최고 수익 부문임을 재확인했다.","eSum":"Gram Car Carriers confirmed PCTC charter rate increases, with one-year time charters for 6,500-CEU ships around $105,000/day, reaffirming car carriers as one of shipping's most profitable sectors.","kImp":"높은 PCTC 용선료는 신조·용대선 의사결정과 선대 확장 전략에 직접 영향을 준다.","eImp":"High PCTC charter rates directly shape newbuild/chartering decisions and fleet-growth strategy.","url":"https://www.lloydslist.com/LL1144094/Gram-Car-Carriers-confirms-PCTC-charter-rates-increase"},{"code":"COMM-4","title":"자동차운반선 선대, 향후 40% 확대 전망","src":"Splash 247","date":"2026","kSum":"수년간 6자릿수 일일 운임을 기록한 자동차운반선 시장이 향후 몇 년간 약 40% 규모로 확대될 전망이다. 대규모 신조 인도가 선복 공급을 늘릴 예정이다.","eSum":"The car carrier fleet is poised to expand by around 40% in the coming years after daily rates spent months in six-digit territory, with heavy newbuild deliveries set to add tonnage.","kImp":"대규모 선복 증가는 중기적으로 PCTC 운임 정상화·하방 압력 요인이 될 수 있다.","eImp":"Large tonnage growth may pressure PCTC rates lower over the medium term.","url":"https://splash247.com/car-carrier-fleet-poised-to-expand-by-40/"},{"code":"COMM-5","title":"주간 탱커·벌크 정기용선료 (6월 10일)","src":"Seatrade Maritime","date":"2026-06-10","kSum":"Seatrade Maritime의 주간 탱커·건화물 정기용선료(6월 10일) 리포트가 발표됐다. 탱커는 지정학 리스크로 강세, 벌크는 물동량 회복 속 견조한 흐름을 보였다.","eSum":"Seatrade Maritime's weekly tanker and dry bulk time charter rates (10 June) were published, showing tankers firm on geopolitical risk and dry bulk steady on recovering volumes.","kImp":"주간 용선료 추이는 용대선·스팟/기간 선택 의사결정의 기준 지표다.","eImp":"Weekly charter trends are the benchmark for chartering and spot/period decisions.","url":"https://www.seatrade-maritime.com/tankers/weekly-tanker-and-dry-bulk-time-charter-rates-10-june"},{"code":"COMM-6","title":"건화물 시장, 2026년 강한 순풍 — 물동량·운임 동반 개선","src":"Hellenic Shipping News","date":"2026","kSum":"건화물 시장이 2026년 강한 순풍을 타고 있다. 1~4월 건화물 물동량이 5억67만 톤으로 전년比 9.6% 증가했고, Ultramax(S11TC)는 평균 $15,328/day, Panamax(P5TC)는 $15,841/day로 2025년 대비 상승했다.","eSum":"The dry bulk market is enjoying strong tailwinds into 2026: Jan-Apr volumes reached 506.7m tonnes (+9.6% y/y), with the Ultramax S11TC averaging $15,328/day and the Panamax P5TC $15,841/day, both up on 2025.","kImp":"벌크 운임·물동량 동반 개선은 용대선 포지셔닝과 선대 운용 수익성에 우호적이다.","eImp":"Improving bulk rates and volumes favour chartering positioning and fleet earnings.","url":"https://www.hellenicshippingnews.com/dry-bulk-market-enjoying-strong-tailwinds-into-2026/"},{"code":"COMM-7","title":"선복 공급·운임이 원유 탱커 선가 상승 견인","src":"Lloyd's List","date":"2026-06","kSum":"선복 공급 여건과 강한 운임이 원유 탱커 선가(자산가치)를 끌어올리고 있다. 높은 수익성이 중고선·신조선 가치 상승으로 이어지고 있다.","eSum":"Fleet supply dynamics and strong freight rates are driving crude tanker values higher, with elevated earnings feeding through to secondhand and newbuild asset prices.","kImp":"선가 상승 국면은 매매·금융·선대 교체 타이밍 판단에 중요한 변수다.","eImp":"Rising vessel values are a key variable for sale-and-purchase, finance and fleet-renewal timing.","url":"https://www.lloydslist.com/LL1155757/Fleet-supply-and-freight-rates-drive-crude-tanker-values-higher"}]},{"code":"GEO","type":"news","kTitle":"Section 16. Maritime Geographical Issue","eTitle":"Section 16. Maritime Geographical Issue","items":[{"code":"GEO-1","title":"이란 공격에 홍해 재검토…박스선 호르무즈 이탈","src":"Lloyd's List","date":"2026-06","kSum":"이란의 공격으로 컨테이너선들이 호르무즈 해협을 빠져나가고 홍해 항로를 재검토하고 있다. 약 170척·45만 TEU가 해협 내에서 출입 제한에 직면한 것으로 전해졌다.","eSum":"Iran attacks are prompting a Red Sea rethink as box shipping exits the Strait of Hormuz; about 170 containerships (~450,000 TEU) are reported facing restrictions on exiting the strait.","kImp":"주요 길목 동시 리스크는 컨테이너 공급망·스케줄 신뢰성에 큰 충격을 준다.","eImp":"Simultaneous chokepoint risk severely disrupts container supply chains and schedule reliability.","url":"https://www.lloydslist.com/LL1156478/Iran-attacks-prompt-Red-Sea-rethink-as-box-shipping-exits-Strait-of-Hormuz"},{"code":"GEO-2","title":"수에즈 통항, 후티 무공격 100일에도 정상比 60% 하회","src":"gCaptain","date":"2026-06","kSum":"후티의 공격이 100일간 없었음에도 수에즈운하 통항량이 정상 대비 약 60% 낮은 수준에 머물고 있다. 선사들의 신뢰 회복 지연으로 희망봉 우회가 지속되고 있다.","eSum":"Suez Canal traffic remains around 60% below normal despite 100 days without Houthi attacks, as slow restoration of carrier confidence keeps Cape diversions in place.","kImp":"운하 통항 회복 지연은 항해거리·연료비·CII 부담을 장기화한다.","eImp":"Slow canal recovery prolongs longer voyages, fuel costs and CII burden.","url":"https://gcaptain.com/suez-canal-traffic-stalls-at-60-below-normal-despite-100-days-without-houthi-attacks/"},{"code":"GEO-3","title":"홍해 복귀 무산…Maersk, 다시 희망봉 우회","src":"gCaptain","date":"2026-06","kSum":"홍해 항로 복귀 움직임이 무산되며 Maersk가 선박을 다시 희망봉(Cape) 우회로 돌렸다. 정세 불안으로 대형 선사의 항로 결정이 보수적으로 회귀하고 있다.","eSum":"The Red Sea comeback faltered as Maersk diverted ships back around the Cape, with major carriers reverting to conservative routing amid instability.","kImp":"선사 항로 회귀는 운임·리드타임·선복 배치의 불확실성을 키운다.","eImp":"Carriers reverting to Cape routing increase uncertainty in rates, lead times and deployment.","url":"https://gcaptain.com/red-sea-comeback-falters-as-maersk-diverts-ships-back-around-cape/"},{"code":"GEO-4","title":"호르무즈 충격파 — Drewry, 탱커 급등·LNG 병목·교역 재편 전망","src":"gCaptain","date":"2026-06","kSum":"Drewry는 호르무즈 사태의 충격파로 탱커 운임 급등, LNG 수송 병목, 교역 흐름의 광범위한 재편(rewiring)을 전망했다. 에너지·원자재 물류 전반에 파급이 예상된다.","eSum":"Drewry sees Strait of Hormuz shockwaves driving a tanker spike, LNG bottlenecks and a broad rewiring of trade flows, with ripple effects across energy and commodity logistics.","kImp":"교역 재편 전망에 맞춰 항로·연료·계약 구조의 시나리오 대응이 필요하다.","eImp":"Anticipated trade rewiring calls for scenario planning across routing, fuel and contracts.","url":"https://gcaptain.com/strait-of-hormuz-shockwaves-drewry-sees-tanker-spike-lng-bottlenecks-and-trade-rewiring-across-shipping/"},{"code":"GEO-5","title":"호르무즈 폐쇄, 건화물 수요 위축","src":"MarineLink","date":"2026-06","kSum":"호르무즈 해협 폐쇄가 건화물(dry bulk) 수요를 위축시키고 있다. 걸프 물동량 차질이 벌크 시장 일부에 하방 압력으로 작용하고 있다.","eSum":"The Strait of Hormuz closure is curbing dry bulk demand, with Gulf cargo disruption weighing on parts of the bulk market.","kImp":"걸프 의존 화물의 차질은 벌크 항로·운임에 지역별 차별화를 만든다.","eImp":"Disruption to Gulf-dependent cargoes creates regional divergence in bulk routes and rates.","url":"https://www.marinelink.com/news/strait-hormuz-closure-curbs-dry-bulk-538580"},{"code":"GEO-6","title":"수에즈·파나마는 통항료 부과…\"호르무즈는 왜 못하나\"","src":"Hellenic Shipping News","date":"2026","kSum":"수에즈·파나마 운하는 통항료를 부과하는데 호르무즈 해협은 왜 통항료를 매기지 못하는지에 대한 분석이 제기됐다. 국제수로의 통항권·과금 논쟁이 부각되고 있다.","eSum":"An analysis asks why the Suez and Panama canals can charge for transit while the Strait of Hormuz cannot, highlighting debates over passage rights and tolling of international waterways.","kImp":"통항권·과금 논쟁은 향후 리스크 비용 배분과 항로 정책에 영향을 줄 수 있다.","eImp":"Passage-rights and tolling debates may shape future risk-cost allocation and routing policy.","url":"https://www.hellenicshippingnews.com/suez-panama-canals-charge-for-transit-why-cant-hormuz/"},{"code":"GEO-7","title":"선사들, 후티 위협 회피해 홍해 우회","src":"Seatrade Maritime","date":"2026","kSum":"선사들이 후티 위협을 피하기 위해 홍해 항로를 우회하고 있다. 안전을 우선한 항로 재설정이 컨테이너 공급망 정상화를 지연시키고 있다.","eSum":"Shipping lines are rerouting from the Red Sea to avoid the Houthi threat, with safety-first re-routing delaying normalisation of container supply chains.","kImp":"안전 우선 우회 지속은 운임·정시성·재고 정책에 구조적 영향을 준다.","eImp":"Persistent safety-first diversion structurally affects rates, punctuality and inventory policy.","url":"https://www.seatrade-maritime.com/containers/shipping-lines-reroute-from-red-sea-avoiding-houthi-threat"}]}]};
